mapper.sql:
SELECT '${pendingStatus}' effectStatus , WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.SEC_MANAGE_ACCT_ID secAcctId , '' AS feeId , '' AS feeName , WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.FINPROD_TYPE2 feeType, WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.FINPROD_TYPE2 AS feeType1, WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.VDATE AS VDATE , WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.MDATE AS MDATE , WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.SETTLE_DATE AS payDate , payAmt.payAmt AS feeAmt , WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.TRADE_AMT AS actPayAmt , WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.TOTLE_TRADE_ID tradeId , WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.VDATE positionStartDate , WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.MDATE positionEndDate, WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.PORTFOLIO_ID portfolioId, WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.INSTITUTION_CODE institutionCode, WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.INSTITUTION_CODE belongInstitutionCode FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL LEFT JOIN ( select WFL_TRD_PRODUCT_DEAL.TOTLE_TRADE_ID,SUM(WFL_PA_TRD_PRODUCT_DEAL.THEORY_INT) payAmt from WFL_PA_TRD_PRODUCT_DEAL,WFL_TRD_PRODUCT_DEAL where WFL_TRD_PRODUCT_DEAL.TRADE_ID =WFL_PA_TRD_PRODUCT_DEAL.TRADE_ID group by WFL_TRD_PRODUCT_DEAL.TOTLE_TRADE_ID ) payAmt ON payAmt.TOTLE_TRADE_ID = WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.TOTLE_TRADE_ID WHERE 1=1 AND WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.TRADE_STATUS=#{effectStatus} AND WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.TG_BUSI_TYPE=#{TG_BUSI_TYPE}
and WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.SEC_MANAGE_ACCT_ID = #{secAcctId}
and WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.MDATE = to_date(#{mdate}, 'yyyy-MM-dd')
and WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.SETTLE_DATE >= to_date(#{payDateStart}, 'yyyy-MM-dd')
and WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.SETTLE_DATE <= to_date(#{payDateEnd}, 'yyyy-MM-dd')
/*新增费用类型检索 guyunfei 20190923 start*/
and WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.FINPROD_TYPE2= #{feeType}
/*新增费用类型检索 guyunfei 20190923 end*/

SELECT '${cancleStatus}' effectStatus , TRD_FIN_PRODUCT_DEAL_TOTAL.SEC_MANAGE_ACCT_ID secAcctId , '' AS feeId , '' AS feeName , TRD_TRADE_FEE_DETAIL.FEE_TYPE feeType, TRD_FIN_PRODUCT_DEAL_TOTAL.FINPROD_TYPE2 AS feeType1, TRD_FIN_PRODUCT_DEAL_TOTAL.VDATE AS VDATE , TRD_FIN_PRODUCT_DEAL_TOTAL.MDATE AS MDATE , TRD_FIN_PRODUCT_DEAL_TOTAL.SETTLE_DATE AS payDate , payAmt.payAmt AS feeAmt , TRD_FIN_PRODUCT_DEAL_TOTAL.TRADE_AMT AS actPayAmt , TRD_FIN_PRODUCT_DEAL_TOTAL.TOTLE_TRADE_ID tradeId , TRD_FIN_PRODUCT_DEAL_TOTAL.VDATE positionStartDate , TRD_FIN_PRODUCT_DEAL_TOTAL.MDATE positionEndDate, TRD_FIN_PRODUCT_DEAL_TOTAL.PORTFOLIO_ID portfolioId, TRD_FIN_PRODUCT_DEAL_TOTAL.INSTITUTION_CODE institutionCode, TRD_FIN_PRODUCT_DEAL_TOTAL.INSTITUTION_CODE belongInstitutionCode FROM TRD_FIN_PRODUCT_DEAL_TOTAL LEFT JOIN TRD_TRADE_FEE_DETAIL ON TRD_FIN_PRODUCT_DEAL_TOTAL.TOTLE_TRADE_ID = TRD_TRADE_FEE_DETAIL.TRADE_ID LEFT JOIN ( select TRD_PRODUCT_DEAL.TOTLE_TRADE_ID,SUM(PA_TRD_PRODUCT_DEAL.THEORY_AMT) payAmt from PA_TRD_PRODUCT_DEAL,TRD_PRODUCT_DEAL where TRD_PRODUCT_DEAL.TRADE_ID =PA_TRD_PRODUCT_DEAL.TRADE_ID group by TRD_PRODUCT_DEAL.TOTLE_TRADE_ID ) payAmt ON payAmt.TOTLE_TRADE_ID = TRD_FIN_PRODUCT_DEAL_TOTAL.TOTLE_TRADE_ID WHERE 1=1 AND TRD_FIN_PRODUCT_DEAL_TOTAL.TRADE_STATUS=#{effectStatus} AND TRD_FIN_PRODUCT_DEAL_TOTAL.IS_CANCEL=#{yesFlag} AND TRD_FIN_PRODUCT_DEAL_TOTAL.TG_BUSI_TYPE=#{TG_BUSI_TYPE}
and TRD_FIN_PRODUCT_DEAL_TOTAL.SEC_MANAGE_ACCT_ID = #{secAcctId}
and TRD_FIN_PRODUCT_DEAL_TOTAL.MDATE = to_date(#{mdate}, 'yyyy-MM-dd')
and TRD_FIN_PRODUCT_DEAL_TOTAL.SETTLE_DATE >= to_date(#{payDateStart}, 'yyyy-MM-dd')
and TRD_FIN_PRODUCT_DEAL_TOTAL.SETTLE_DATE <= to_date(#{payDateEnd}, 'yyyy-MM-dd')
/*新增费用类型检索 guyunfei 20190923 start*/
and TRD_FIN_PRODUCT_DEAL_TOTAL.FINPROD_TYPE2= #{feeType}
/*新增费用类型检索 guyunfei 20190923 end*/

SELECT '${effectStatus}' effectStatus , TRD_FIN_PRODUCT_DEAL_TOTAL.SEC_MANAGE_ACCT_ID secAcctId , '' AS feeId , '' AS feeName , TRD_TRADE_FEE_DETAIL.FEE_TYPE feeType, TRD_FIN_PRODUCT_DEAL_TOTAL.FINPROD_TYPE2 AS feeType1, TRD_FIN_PRODUCT_DEAL_TOTAL.VDATE AS VDATE , TRD_FIN_PRODUCT_DEAL_TOTAL.MDATE AS MDATE , TRD_FIN_PRODUCT_DEAL_TOTAL.SETTLE_DATE AS payDate , payAmt.payAmt AS feeAmt , TRD_FIN_PRODUCT_DEAL_TOTAL.TRADE_AMT AS actPayAmt , TRD_FIN_PRODUCT_DEAL_TOTAL.TOTLE_TRADE_ID tradeId , TRD_FIN_PRODUCT_DEAL_TOTAL.VDATE positionStartDate , TRD_FIN_PRODUCT_DEAL_TOTAL.MDATE positionEndDate, TRD_FIN_PRODUCT_DEAL_TOTAL.PORTFOLIO_ID portfolioId, TRD_FIN_PRODUCT_DEAL_TOTAL.INSTITUTION_CODE institutionCode, TRD_FIN_PRODUCT_DEAL_TOTAL.INSTITUTION_CODE belongInstitutionCode FROM TRD_FIN_PRODUCT_DEAL_TOTAL LEFT JOIN TRD_TRADE_FEE_DETAIL ON TRD_FIN_PRODUCT_DEAL_TOTAL.TOTLE_TRADE_ID = TRD_TRADE_FEE_DETAIL.TRADE_ID LEFT JOIN ( select TRD_PRODUCT_DEAL.TOTLE_TRADE_ID,SUM(PA_TRD_PRODUCT_DEAL.THEORY_AMT) payAmt from PA_TRD_PRODUCT_DEAL,TRD_PRODUCT_DEAL where TRD_PRODUCT_DEAL.TRADE_ID =PA_TRD_PRODUCT_DEAL.TRADE_ID group by TRD_PRODUCT_DEAL.TOTLE_TRADE_ID ) payAmt ON payAmt.TOTLE_TRADE_ID = TRD_FIN_PRODUCT_DEAL_TOTAL.TOTLE_TRADE_ID WHERE 1=1 AND TRD_FIN_PRODUCT_DEAL_TOTAL.TRADE_STATUS=#{effectStatus} AND TRD_FIN_PRODUCT_DEAL_TOTAL.IS_CANCEL=#{noFlag} AND TRD_FIN_PRODUCT_DEAL_TOTAL.TG_BUSI_TYPE=#{TG_BUSI_TYPE}
and TRD_FIN_PRODUCT_DEAL_TOTAL.SEC_MANAGE_ACCT_ID = #{secAcctId}
and TRD_FIN_PRODUCT_DEAL_TOTAL.MDATE = to_date(#{mdate}, 'yyyy-MM-dd')
and TRD_FIN_PRODUCT_DEAL_TOTAL.SETTLE_DATE >= to_date(#{payDateStart}, 'yyyy-MM-dd')
and TRD_FIN_PRODUCT_DEAL_TOTAL.SETTLE_DATE <= to_date(#{payDateEnd}, 'yyyy-MM-dd')
/*新增费用类型检索 guyunfei 20190923 start*/
and TRD_FIN_PRODUCT_DEAL_TOTAL.FINPROD_TYPE2= #{feeType}
/*新增费用类型检索 guyunfei 20190923 end*/

mapper.select:
select MST_FEEINFO.FEE_ID id, MST_FEEINFO.FEE_NAME text from MST_FEEINFO where MST_FEEINFO.APPLY_TYPE in (#{relationProd}, #{relationOther}) AND MST_FEEINFO.FEE_TYPE IN (#{feeType06},#{feeType07},#{feeType14})
and (MST_FEEINFO.FEE_ID like concat(concat('%', #{search}), '%') or MST_FEEINFO.FEE_NAME like concat(concat('%', #{search}), '%'))
and MST_FEEINFO.FEE_ID = #{initValue}

select MST_FEEINFO.FEE_ID id, MST_FEEINFO.FEE_NAME text from MST_FEEINFO where MST_FEEINFO.APPLY_TYPE in (#{relationProd}, #{relationOther}) and MST_FEEINFO.CHARGE_TYPE = #{chargeType02} AND MST_FEEINFO.FEE_TYPE IN (#{feeType06},#{feeType07},#{feeType14})
and (MST_FEEINFO.FEE_ID like concat(concat('%', #{search}), '%') or MST_FEEINFO.FEE_NAME like concat(concat('%', #{search}), '%'))
and MST_FEEINFO.FEE_ID = #{initValue}
union all select DISTINCT MST_FEEINFO.FEE_ID id, MST_FEEINFO.FEE_ID || ':' || MST_FEEINFO.FEE_NAME text from FIN_CASH_INFO,FIN_PRODUCT,MST_FEEINFO,FIN_PRODUCT_ADD ,FIN_CASH_PAY_RULE ,PTL_SEC_ACCT PSA,STL_SEC_ACCT_INFO SSAI where MST_FEEINFO.APPLY_TYPE in (#{relationProd}, #{relationOther}) and FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID and FIN_CASH_INFO.FEE_ID = MST_FEEINFO.FEE_ID and FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID and FIN_CASH_INFO.CASH_ID = FIN_CASH_PAY_RULE.CASH_ID and PSA.PORTFOLIO_ID = FIN_PRODUCT_ADD.PORTFOLIO_ID and SSAI.SEC_ACCT_ID = PSA.ACCT_NO and FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1} and FIN_CASH_PAY_RULE.PAY_CYCLE = #{payCycle} and SSAI.SEC_ACCT_ID = #{secAcctId} and MST_FEEINFO.CHARGE_TYPE = #{chargeType01} AND (FIN_CASH_INFO.IS_CALC IS NULL OR FIN_CASH_INFO.IS_CALC = #{yes}) AND MST_FEEINFO.FEE_TYPE IN (#{feeType06},#{feeType07},#{feeType14})
and (MST_FEEINFO.FEE_ID like concat(concat('%', #{search}), '%') or MST_FEEINFO.FEE_NAME like concat(concat('%', #{search}), '%'))
and MST_FEEINFO.FEE_ID = #{initValue}

    	select distinct to_char(max(TRD_PRODUCT_DEAL.MDATE), 'yyyy-MM-dd')
    	from TRD_FIN_PRODUCT_DEAL_TOTAL, TRD_PRODUCT_DEAL, TRD_TRADE_FEE_DETAIL
    	where TRD_FIN_PRODUCT_DEAL_TOTAL.TOTLE_TRADE_ID = TRD_PRODUCT_DEAL.TOTLE_TRADE_ID
    	and TRD_PRODUCT_DEAL.TRADE_ID = TRD_TRADE_FEE_DETAIL.TRADE_ID

			and TRD_FIN_PRODUCT_DEAL_TOTAL.SEC_MANAGE_ACCT_ID = #{secAcctId}

    	and TRD_FIN_PRODUCT_DEAL_TOTAL.IS_CANCEL = #{isCancel}
		and TRD_FIN_PRODUCT_DEAL_TOTAL.TRADE_STATUS = #{tradeStatus}
    	and TRD_TRADE_FEE_DETAIL.FEE_TYPE = #{feeType1}
    	and #{cdate} >= to_char(TRD_PRODUCT_DEAL.MDATE, 'yyyy-MM-dd')

    	select sum(NVL(PTL_FEE_POSITION.TDY_ACCUMUL_PAY_FEE,0)) 
    	from PTL_FEE_POSITION

			LEFT JOIN PTL_SEC_ACCT PSA 
			ON PSA.PORTFOLIO_ID = PTL_FEE_POSITION.PORTFOLIO_ID
			INNER JOIN STL_SEC_ACCT_INFO SSAI 
      		ON SSAI.SEC_ACCT_ID = PSA.ACCT_NO AND SSAI.REGIST_ORG = PTL_FEE_POSITION.PTL_FEE_PLACE

   		WHERE PTL_FEE_POSITION.PTL_FEE_TYPE = #{feeType1}
			AND PTL_FEE_POSITION.CDATE = to_date(#{cdate}, 'yyyy-MM-dd')-1

				AND PSA.ACCT_NO = #{secAcctId}


				AND PTL_FEE_POSITION.PTL_FEE_PLACE = #{org}

SELECT SUM(NVL(TDY_UNPAID_INTINCEXP, 0)) FROM (
	select TDY_UNPAID_INTINCEXP from BOK_POSITION_PRDFEE
	where FEE_TYPE = #{feeType}
	  and CDATE = to_date(#{cdate}, 'yyyy-MM-dd') - 1
	  and FINPROD_ID = #{finprodId}
	  and P_FINPROD_ID IS NULL
	UNION ALL
	select TDY_UNPAID_INTINCEXP from BOK_POSITION_PRDFEE
	where FEE_TYPE = #{feeType}
	  and CDATE = to_date(#{cdate}, 'yyyy-MM-dd') - 1
	  and FINPROD_ID = #{finprodId}
	  and P_FINPROD_ID IS not NULL
	)

		select FIN_FLOAT_ACCRUAL_SCHE.ACCR_STR_DATE 
		from fin_cash_info ,FIN_FLOAT_ACCRUAL_SCHE  
        where fin_cash_info.finprod_id = #{finprodId}
        and fin_cash_info.cash_type_1 = #{CASH_TYPE_1_03}
        and fin_cash_info.cash_type_2 = #{CASH_TYPE_2_C04}
        and FIN_FLOAT_ACCRUAL_SCHE.CASH_ID = fin_cash_info.cash_id
        and FIN_FLOAT_ACCRUAL_SCHE.ACCR_DATE = to_date(#{cdate}, 'yyyy-MM-dd')

SELECT ptl.PORTFOLIO_ID ptlId, /*组合代码*/ ptl.PORTFOLIO_NAME portFolioName, /*组合名称*/ tpd.FINPROD_TYPE2 tradeType, /*交易品种*/ tpd.PS ps, /*交易方向*/ asset.FINPROD_MARKET_ID assetCode, /*资产代码*/ asset.finprod_abbr assetName, /*资产名称*/ tpd.TRADE_AMT tradeAmt, /*交易金额*/ to_char(tpd.TRADE_DATE, 'yyyy-MM-dd') tradeDate, /*交易日期*/ tdf.FEE_TYPE feeType, /*费用类型*/ tdf.FEE_AMT payAmt, /*理论费用*/ tpd.trade_id tradeId, /*交易编号*/ tpd.SEC_MANAGE_ACCT_ID secAcctId /*证券账户*/ FROM TRD_PRODUCT_DEAL tpd LEFT JOIN TRD_PRODUCT_DEAL_ADD tpda ON tpd.trade_id = tpda.trade_id LEFT JOIN TRD_TRADE_FEE_DETAIL tdf ON tpd.trade_id = tdf.trade_id LEFT JOIN PTL_PORTFOLIO ptl ON tpda.PORTFOLIO_ID = ptl.PORTFOLIO_ID LEFT JOIN fin_product asset ON tpd.finprod_id = asset.finprod_id WHERE tpd.TRADE_STATUS = #{TRADE_STATUS_01} AND tpd.IS_CANCEL = #{IS_CANCEL_N}
AND tpd.SEC_MANAGE_ACCT_ID = #{secAcctId}
AND tdf.fee_type = #{feeType1} AND tpd.TRADE_DATE >= to_date(#{startDate}, 'yyyy-MM-dd') AND to_date(#{enddate}, 'yyyy-MM-dd') > tpd.TRADE_DATE AND tpda.PORTFOLIO_ID = #{ptlId} AND tpd.FINPROD_TYPE2 != #{FINPROD_TYPE2_C11}

		select 
        from PTL_TRADE
        where BUSI_NO = #{tradeId}

select 
from TRD_TRADE_FEE_DETAIL
where TRADE_ID = #{tradeId}

select FIN_PRODUCT_ADD.FINPROD_ID finprodId, BOK_POSITION_PRDFEE.BRANCH branch, '' sFinprodId, SUM(NVL(BOK_POSITION_PRDFEE.TDY_UNPAID_INTINCEXP, 0)) actPayAmt from BOK_POSITION_PRDFEE, FIN_PRODUCT_ADD, FIN_PRODUCT where BOK_POSITION_PRDFEE.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID and FIN_PRODUCT_ADD.FINPROD_ID = FIN_PRODUCT.FINPROD_ID
and FIN_PRODUCT_ADD.PORTFOLIO_ID = #{ptlId}
and BOK_POSITION_PRDFEE.FEE_TYPE = #{feeType}
and BOK_POSITION_PRDFEE.CDATE = to_date(#{calcEndDate}, 'yyyy-MM-dd')
and BOK_POSITION_PRDFEE.CDATE = to_date(#{calcEndDate}, 'yyyy-MM-dd') -1
and BOK_POSITION_PRDFEE.P_FINPROD_ID is NULL group by FIN_PRODUCT_ADD.FINPROD_ID, BOK_POSITION_PRDFEE.BRANCH union all
select FIN_PRODUCT_ADD.FINPROD_ID finprodId, BOK_POSITION_PRDFEE.BRANCH branch, BOK_POSITION_PRDFEE.FINPROD_ID sFinprodId, SUM(NVL(BOK_POSITION_PRDFEE.TDY_UNPAID_INTINCEXP, 0)) actPayAmt from BOK_POSITION_PRDFEE, FIN_PRODUCT_ADD, FIN_PRODUCT,FIN_PRODUCT F1 where BOK_POSITION_PRDFEE.P_FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID and FIN_PRODUCT_ADD.FINPROD_ID = FIN_PRODUCT.FINPROD_ID AND F1.P_FINPROD_ID=FIN_PRODUCT_ADD.FINPROD_ID
and FIN_PRODUCT_ADD.PORTFOLIO_ID = #{ptlId}
and BOK_POSITION_PRDFEE.FEE_TYPE = #{feeType}
and BOK_POSITION_PRDFEE.CDATE = to_date(#{calcEndDate}, 'yyyy-MM-dd')
and BOK_POSITION_PRDFEE.CDATE = to_date(#{calcEndDate}, 'yyyy-MM-dd') -1
group by FIN_PRODUCT_ADD.FINPROD_ID, BOK_POSITION_PRDFEE.BRANCH,BOK_POSITION_PRDFEE.FINPROD_ID union all
select FIN_PRODUCT_ADD.FINPROD_ID finprodId, 0 branch, '' sFinprodId, SUM(NVL(PTL_FEE_POSITION.TDY_ACCUMUL_PAY_FEE, 0)) actPayAmt from PTL_FEE_POSITION, FIN_PRODUCT_ADD, FIN_PRODUCT where PTL_FEE_POSITION.PORTFOLIO_ID = FIN_PRODUCT_ADD.PORTFOLIO_ID and FIN_PRODUCT_ADD.FINPROD_ID = FIN_PRODUCT.FINPROD_ID
and FIN_PRODUCT_ADD.PORTFOLIO_ID = #{ptlId}
and PTL_FEE_POSITION.PTL_FEE_TYPE = #{feeType} and PTL_FEE_POSITION.CDATE = to_date(#{calcEndDate}, 'yyyy-MM-dd') - 1 and FIN_PRODUCT.p_Finprod_Id is null group by FIN_PRODUCT_ADD.FINPROD_ID

SELECT TEMP.finprodMarketId finprodMarketId, TEMP.finprodId finprodId, TEMP.sFinprodId sFinprodId, TEMP.feeId feeId, sys_datadict_list.item_value basicBill, TEMP.feeName feeName, TEMP.feeType feeType, TEMP.calcStartDate calcStartDate, TEMP.calcEndDate calcEndDate, TEMP.ccy ccy, TEMP.actPayAmt actPayAmt, TEMP.payAmt payAmt FROM( SELECT FIN_PRODUCT_ADD.PORTFOLIO_ID finprodMarketId ,FIN_PRODUCT.Finprod_Id finprodId ,NULL as sFinprodId ,MST_FEEINFO.FEE_ID feeId ,MST_FEEINFO.BASIC_BILL basicBill ,MST_FEEINFO.Fee_Name feeName ,BOK_POSITION_PRDFEE.FEE_TYPE feeType ,TRD_PRODUCT_DEAL.MDATE as calcStartDate ,to_date(#{calcEndDate}, 'yyyy-MM-dd') calcEndDate ,FIN_CASH_INFO.ccy ,BOK_POSITION_PRDFEE.TDY_UNPAID_INTINCEXP as actPayAmt ,BOK_POSITION_PRDFEE.TDY_UNPAID_INTINCEXP as payAmt FROM FIN_CASH_INFO INNER JOIN FIN_CASH_PAY_RULE ON FIN_CASH_INFO.CASH_ID = FIN_CASH_PAY_RULE.CASH_ID
AND FIN_CASH_PAY_RULE.PAY_CYCLE != #{payCycle}
AND FIN_CASH_PAY_RULE.PAY_CYCLE = #{payCycle}
INNER JOIN MST_FEEINFO ON FIN_CASH_INFO.FEE_ID = MST_FEEINFO.FEE_ID AND MST_FEEINFO.CHARGE_TYPE IN(#{chargeType}) INNER JOIN BOK_POSITION_PRDFEE ON FIN_CASH_INFO.FINPROD_ID = BOK_POSITION_PRDFEE.FINPROD_ID AND FIN_CASH_INFO.BRANCH = BOK_POSITION_PRDFEE.BRANCH and FIN_CASH_INFO.CASH_TYPE_2 = BOK_POSITION_PRDFEE.FEE_TYPE LEFT JOIN ( SELECT MDATE,FINPROD_ID,BRANCH,FINPROD_TYPE2 FROM TRD_PRODUCT_DEAL S WHERE S.PS = #{ps} AND S.IS_CANCEL = #{isCancel} AND MDATE = (select MAX(d.MDATE) from TRD_PRODUCT_DEAL d where d.PS = #{ps} AND d.MDATE < to_date(#{calcEndDate}, 'yyyy-MM-dd') AND d.IS_CANCEL = #{isCancel} AND S.FINPROD_ID=D.FINPROD_ID AND S.BRANCH=D.BRANCH AND S.FINPROD_TYPE2=D.FINPROD_TYPE2 ))TRD_PRODUCT_DEAL on FIN_CASH_INFO.FINPROD_ID = TRD_PRODUCT_DEAL.FINPROD_ID AND FIN_CASH_INFO.BRANCH = TRD_PRODUCT_DEAL.BRANCH AND TRD_PRODUCT_DEAL.FINPROD_TYPE2 = BOK_POSITION_PRDFEE.FEE_TYPE LEFT JOIN FIN_PRODUCT ON FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID LEFT JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID WHERE FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1} AND FIN_PRODUCT.P_FINPROD_ID is null AND FIN_PRODUCT_ADD.PORTFOLIO_ID = #{ptlId} AND FIN_PRODUCT.FINPROD_ID = #{finprodId} AND MST_FEEINFO.FEE_ID = #{feeId} AND BOK_POSITION_PRDFEE.CDATE = (SELECT max(B.CDATE) FROM BOK_POSITION_PRDFEE B WHERE B.FINPROD_ID = BOK_POSITION_PRDFEE.FINPROD_ID AND B.BRANCH = BOK_POSITION_PRDFEE.BRANCH AND BOK_POSITION_PRDFEE.FEE_TYPE = B.FEE_TYPE AND B.CDATE <to_date(#{calcEndDate}, 'yyyy-MM-dd')) UNION SELECT FIN_PRODUCT_ADD.PORTFOLIO_ID finprodMarketId ,FIN_PRODUCT1.FINPROD_MARKET_ID finprodId ,FIN_PRODUCT.FINPROD_ID as sFinprodId ,MST_FEEINFO.FEE_ID feeId ,MST_FEEINFO.BASIC_BILL basicBill ,MST_FEEINFO.Fee_Name feeName ,BOK_POSITION_PRDFEE.FEE_TYPE feeType ,TRD_PRODUCT_DEAL.MDATE as calcStartDate ,to_date(#{calcEndDate}, 'yyyy-MM-dd') calcEndDate ,FIN_CASH_INFO.ccy ,BOK_POSITION_PRDFEE.TDY_UNPAID_INTINCEXP as actPayAmt ,BOK_POSITION_PRDFEE.TDY_UNPAID_INTINCEXP as payAmt FROM FIN_CASH_INFO INNER JOIN FIN_CASH_PAY_RULE ON FIN_CASH_INFO.CASH_ID = FIN_CASH_PAY_RULE.CASH_ID
AND FIN_CASH_PAY_RULE.PAY_CYCLE != #{payCycle}
AND FIN_CASH_PAY_RULE.PAY_CYCLE = #{payCycle}
INNER JOIN MST_FEEINFO ON FIN_CASH_INFO.FEE_ID = MST_FEEINFO.FEE_ID AND MST_FEEINFO.CHARGE_TYPE IN(#{chargeType}) INNER JOIN BOK_POSITION_PRDFEE ON FIN_CASH_INFO.FINPROD_ID = BOK_POSITION_PRDFEE.FINPROD_ID AND FIN_CASH_INFO.BRANCH = BOK_POSITION_PRDFEE.BRANCH and FIN_CASH_INFO.CASH_TYPE_2 = BOK_POSITION_PRDFEE.FEE_TYPE LEFT JOIN ( SELECT MDATE,FINPROD_ID,BRANCH,FINPROD_TYPE2 FROM TRD_PRODUCT_DEAL S WHERE S.PS = #{ps} AND S.IS_CANCEL = #{isCancel} AND MDATE = (select MAX(d.MDATE) from TRD_PRODUCT_DEAL d where d.PS = #{ps} AND d.MDATE < to_date(#{calcEndDate}, 'yyyy-MM-dd') AND d.IS_CANCEL = #{isCancel} AND S.FINPROD_ID=D.FINPROD_ID AND S.BRANCH=D.BRANCH AND S.FINPROD_TYPE2=D.FINPROD_TYPE2 ))TRD_PRODUCT_DEAL on FIN_CASH_INFO.FINPROD_ID = TRD_PRODUCT_DEAL.FINPROD_ID AND FIN_CASH_INFO.BRANCH = TRD_PRODUCT_DEAL.BRANCH AND TRD_PRODUCT_DEAL.FINPROD_TYPE2 = BOK_POSITION_PRDFEE.FEE_TYPE LEFT JOIN FIN_PRODUCT ON FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID LEFT JOIN FIN_PRODUCT FIN_PRODUCT1 ON BOK_POSITION_PRDFEE.FINPROD_ID = FIN_PRODUCT1.FINPROD_ID
LEFT JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT1.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID WHERE FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1} AND FIN_PRODUCT.P_FINPROD_ID is not null AND FIN_PRODUCT_ADD.PORTFOLIO_ID = #{ptlId} AND FIN_PRODUCT.P_FINPROD_ID = #{finprodId} AND MST_FEEINFO.FEE_ID = #{feeId} AND BOK_POSITION_PRDFEE.CDATE = (SELECT max(B.CDATE) FROM BOK_POSITION_PRDFEE B WHERE B.FINPROD_ID = BOK_POSITION_PRDFEE.FINPROD_ID AND B.BRANCH = BOK_POSITION_PRDFEE.BRANCH AND BOK_POSITION_PRDFEE.FEE_TYPE = B.FEE_TYPE
AND B.CDATE <to_date(#{calcEndDate}, 'yyyy-MM-dd'))
union all
select PTL_PORTFOLIO.PORTFOLIO_ID finprodMarketId ,FIN_PRODUCT_ADD.FINPROD_ID finprodId ,'' as sFinprodId ,MST_FEEINFO.FEE_ID feeId ,MST_FEEINFO.BASIC_BILL basicBill ,MST_FEEINFO.Fee_Name feeName ,PTL_FEE_POSITION.PTL_FEE_TYPE feeType ,nvl(TRD_PRODUCT_DEAL.MDATE,PTL_PORTFOLIO.vdate) as calcStartDate ,to_date(#{calcEndDate}, 'yyyy-MM-dd') calcEndDate ,FIN_CASH_INFO.ccy ,PTL_FEE_POSITION.TDY_ACCUMUL_PAY_FEE as actPayAmt ,PTL_FEE_POSITION.TDY_ACCUMUL_PAY_FEE as payAmt from PTL_FEE_POSITION, FIN_PRODUCT_ADD, PTL_PORTFOLIO ,MST_FEEINFO, FIN_CASH_INFO LEFT JOIN ( SELECT MDATE,FINPROD_ID,BRANCH,FINPROD_TYPE2 FROM TRD_PRODUCT_DEAL S WHERE S.PS = #{ps} AND S.IS_CANCEL = #{isCancel} AND MDATE = (select MAX(d.MDATE) from TRD_PRODUCT_DEAL d where d.PS = #{ps} AND d.MDATE < to_date(#{calcEndDate}, 'yyyy-MM-dd') AND d.IS_CANCEL = #{isCancel} AND S.FINPROD_ID=D.FINPROD_ID AND S.BRANCH=D.BRANCH AND S.FINPROD_TYPE2=D.FINPROD_TYPE2 ))TRD_PRODUCT_DEAL on FIN_CASH_INFO.FINPROD_ID = TRD_PRODUCT_DEAL.FINPROD_ID AND FIN_CASH_INFO.BRANCH = TRD_PRODUCT_DEAL.BRANCH and FIN_CASH_INFO.CASH_TYPE_2 = TRD_PRODUCT_DEAL.FINPROD_TYPE2 where PTL_FEE_POSITION.PORTFOLIO_ID = FIN_PRODUCT_ADD.PORTFOLIO_ID and FIN_PRODUCT_ADD.PORTFOLIO_ID = PTL_PORTFOLIO.PORTFOLIO_ID and FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID and FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1} and FIN_CASH_INFO.CASH_TYPE_2 = #{cashType2_C04} and FIN_CASH_INFO.FEE_ID = MST_FEEINFO.FEE_ID and PTL_FEE_POSITION.PTL_FEE_TYPE = FIN_CASH_INFO.CASH_TYPE_2 AND MST_FEEINFO.CHARGE_TYPE = #{chargeType} and FIN_PRODUCT_ADD.PORTFOLIO_ID = #{ptlId} and PTL_FEE_POSITION.PTL_FEE_TYPE = #{feeType} and PTL_FEE_POSITION.CDATE = to_date(#{calcEndDate}, 'yyyy-MM-dd') - 1 and PTL_PORTFOLIO.PROFIT_TYPE = #{profitType} )TEMP left join sys_datadict_list on TEMP.basicBill = sys_datadict_list.item_code and dict_code = 'BILL_BASE_FEE_KIND'


    select sum(PTPD.THEORY_AMT)-sum(TTFD.FEE_AMT) from 
    PA_TRD_PRODUCT_DEAL PTPD ,TRD_TRADE_FEE_DETAIL TTFD,TRD_PRODUCT_DEAL TPD,FIN_PRODUCT_ADD FPA
		WHERE TTFD.TRADE_ID = PTPD.TRADE_ID
		AND TPD.TRADE_ID = PTPD.TRADE_ID
		AND FPA.FINPROD_ID = TPD.FINPROD_ID
		AND TPD.FINPROD_ID = #{finprodId}
	    AND TPD.IS_CANCEL = #{noFlag}
		AND TPD.TRADE_STATUS = #{tradeStatus}

	  	AND FPA.PORTFOLIO_ID = #{ptlId}


		AND TTFD.FEE_ID = #{feeId}


		AND TPD.TRADE_DATE <= to_date(#{payDate},'yyyy-MM-dd')

		AND TPD.IS_CLEAN = #{isClean}

select CASH_TYPE_2 from FIN_CASH_INFO
where FINPROD_ID = #{finprodId}
and FEE_ID = #{feeId}

select DISTINCT CASH_TYPE_2 from FIN_CASH_INFO
where FINPROD_ID IN (SELECT FINPROD_ID FROM FIN_PRODUCT WHERE P_FINPROD_ID = #{finprodId}) 
and FEE_ID = #{feeId}

  select nvl(sum(nvl(fee_amt,0)),0) from trd_trade_fee_detail where fee_type=#{feeType1} and trade_id in(
select deal.trade_id from trd_product_deal deal,trd_product_deal_add add1 ,fin_product prod  
where prod.finprod_type2 in('F01','F02','F03','F04','F05') and is_cancel='N'
and add1.trade_id=deal.trade_id and add1.portfolio_id=#{ptlId}  
and deal.trade_date <= to_date(#{cdate}, 'yyyy-MM-dd') and deal.finprod_id=prod.finprod_id and prod.REGIST_ORG=#{org}
)

	select nvl(sum(nvl(trade_amt,0)),0) 
	from  trd_product_deal deal,trd_product_deal_add add1 ,
		fin_product prod,TRD_TRADE_FEE_DETAIL feed
	where  
	deal.finprod_id=prod.finprod_id 
	and deal.TRADE_ID = feed.TRADE_ID
	AND deal.IS_CANCEL = #{noFlag}
	and feed.fee_type = #{feeType1} 
	and deal.trade_id = add1.trade_id

 	and deal.SEC_MANAGE_ACCT_ID = #{secAcctId} 


 	and  deal.REGIST_ORG=#{org} 

	and deal.trade_date = to_date(#{cdate}, 'yyyy-MM-dd')

       select count(*)
        from FIN_CASH_INFO,FIN_PRODUCT,MST_FEEINFO,FIN_PRODUCT_ADD ,FIN_CASH_PAY_RULE
        where MST_FEEINFO.APPLY_TYPE in (#{relationProd}, #{relationOther})
        and FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID
        and FIN_CASH_INFO.FEE_ID = MST_FEEINFO.FEE_ID
        and FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID
        and FIN_CASH_INFO.CASH_ID = FIN_CASH_PAY_RULE.CASH_ID
        and FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1}
        and FIN_CASH_PAY_RULE.PAY_CYCLE = #{payCycle}
        and decode(MST_FEEINFO.FEE_TYPE, #{feeType_03}, 0, #{feeType_04}, 0, #{feeType_12}, 0, 1) = 1

        and FIN_CASH_INFO.FINPROD_ID = #{finprodId}



			and FIN_PRODUCT_ADD.PORTFOLIO_ID in 

				#{item}


      and MST_FEEINFO.CHARGE_TYPE = #{chargeType01}

          and MST_FEEINFO.FEE_ID = #{initValue}

         and not exists (select 1 from TRD_PRODUCT_DEAL where FIN_CASH_INFO.CASH_ID = TRD_PRODUCT_DEAL.CASH_ID
         and TRD_PRODUCT_DEAL.IS_CANCEL = #{noFlag}
         and TRD_PRODUCT_DEAL.TRADE_STATUS = #{tradeStatus}

        and FIN_CASH_INFO.FINPROD_ID = #{finprodId}
        )

select FIN_CASH_INFO.CASH_ID from FIN_CASH_INFO
where FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1}
  and FIN_CASH_INFO.FEE_ID = #{feeId}
  and FIN_CASH_INFO.FINPROD_ID = #{finprodId}

SELECT sum(NVL(PTL_FEE_POSITION.TDY_ACCUMUL_PAY_FEE,0)) FROM PTL_FEE_POSITION
LEFT JOIN PTL_SEC_ACCT PSA ON PSA.PORTFOLIO_ID = PTL_FEE_POSITION.PORTFOLIO_ID INNER JOIN STL_SEC_ACCT_INFO SSAI ON SSAI.SEC_ACCT_ID = PSA.ACCT_NO
AND SSAI.REGIST_ORG = PTL_FEE_POSITION.PTL_FEE_PLACE
WHERE PTL_FEE_POSITION.PTL_FEE_TYPE = #{feeType1} AND PTL_FEE_POSITION.CDATE = to_date(#{cdate}, 'yyyy-MM-dd')-1
AND PSA.ACCT_NO = #{secAcctId}
AND PTL_FEE_POSITION.PTL_FEE_PLACE = #{org}

select count(1) from WFL_TRD_PRODUCT_DEAL 
where TRADE_ID = #{tradeId,jdbcType=VARCHAR}
    or P_TRADE_ID = #{tradeId,jdbcType=VARCHAR}

select count(1) from TRD_PRODUCT_DEAL 
where 
    (TRADE_ID = #{tradeId,jdbcType=VARCHAR}
    or P_TRADE_ID = #{tradeId,jdbcType=VARCHAR})
    and 
    (IS_CANCEL = #{YES_NO_YES,jdbcType=VARCHAR}
    or TRADE_STATUS = #{TRADE_STATUS_03,jdbcType=VARCHAR}
    )
